import java.util.*;

class Solution {
  public boolean isReflected(int[][] points) {
    int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
    Set<Long> set = new HashSet<>();
    for (int[] p : points) {
      min = Math.min(min, p[0]);
      max = Math.max(max, p[0]);
      set.add(key(p[0], p[1]));
    }
    long sum = (long) min + max; // reflection of x is sum - x
    for (int[] p : points) if (!set.contains(key(sum - p[0], p[1]))) return false;
    return true;
  }

  private long key(long x, long y) {
    return x * 1_000_000_007L + y;
  }
}
